package com.siiiweb.article.config;import org.springframework.amqp.core.*;import org.springframework.context.annotation.*;@Configuration public class RabbitConfig{@Bean TopicExchange articleExchange(){return new TopicExchange("siiiweb.article.exchange");}@Bean Queue indexQueue(){return new Queue("siiiweb.search.index.queue");}@Bean Binding binding(){return BindingBuilder.bind(indexQueue()).to(articleExchange()).with("article.*");}}
